mapper.select:
select b.*,tl.org_name,tl.org_location from sys_org_b b join sys_org_tl tl on tl.org_id = b.org_id and tl.language = #{language}
and b.org_status = #{orgStatus}
and org_code like CONCAT( CONCAT('%',#{orgCode} ),'%')
and org_name like CONCAT( CONCAT('%',#{orgName} ),'%')
order by b.org_id desc

mapper.update:
update sys_org_tl
org_name = #{orgName}, org_location = #{orgLocation}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where org_id = #{orgId} and language = #{language}

update sys_org_b

    org_status = #{orgStatus},
    LAST_UPDATE_BY = #{lastUpdateBy},
    LAST_UPDATE_DATE = #{lastUpdateDate},
    LAST_UPDATE_LOGIN = #{lastUpdateLogin}

where org_id = #{orgId}

update sys_org_b

    org_status = #{orgStatus},
    LAST_UPDATE_BY = #{lastUpdateBy},
    LAST_UPDATE_DATE = #{lastUpdateDate},
    LAST_UPDATE_LOGIN = #{lastUpdateLogin}

where org_code = #{orgCode}

